<script setup>
import {reactive,computed} from 'vue';
import {usePlanner} from './usePlanner.js';
import Timeline from './Timeline.vue';
import Inspector from './Inspector.vue';
const vm=reactive(usePlanner());
const navigation=[
  {id:'timeline',label:'Einsatzplan',icon:'i-lucide-calendar-range'},
  {id:'roles',label:'Rollen & Aufwand',icon:'i-lucide-users'},
  {id:'analysis',label:'Auswertung',icon:'i-lucide-chart-column'},
  {id:'calendar',label:'Arbeitskalender',icon:'i-lucide-calendar-days'}
];
const titles={timeline:'Ressourceneinsatzplan',roles:'Rollen & Aufwand',analysis:'Aufwand im Zeitverlauf',calendar:'Arbeitskalender',connections:'Verknüpfungen',files:'Import & Export',help:'So rechnet dein Plan',settings:'Darstellung & Vault'};
const subtitles={timeline:'Rollen einplanen. Zeit blocken. Aufwand im Blick behalten.',roles:'Jede Rolle mit ihrem geplanten Aufwand über die gesamte Laufzeit.',analysis:'Personentage je Zeitraum und Rolle – aus denselben Tageswerten berechnet.',calendar:'Arbeitstage, Feiertage und gesperrte Zeit bestimmen die verfügbare Kapazität.',connections:'Ressourcenplanung mit Produktkontext verbinden.',files:'Pläne mitnehmen, als Obsidian-Notiz ablegen oder weiter auswerten.',help:'FTE, Arbeitstage und Sperrzeiten nachvollziehbar verbinden.',settings:'Eine vertraute Arbeitsumgebung und ein klarer Ort für deine Pläne.'};
const title=computed(()=>titles[vm.view]||titles.timeline);
const subtitle=computed(()=>subtitles[vm.view]||subtitles.timeline);
const previewPlans=computed(()=>vm.staged?.plans?.map(p=>({id:p.id,name:p.name,start:p.start,end:p.end,roles:p.roles.length,allocations:p.allocations.length}))||[]);
const familyPeers=computed(()=>Object.entries(vm.APPS).filter(([key])=>key!=='resource-atlas'));
const roleColor=r=>r.color?.startsWith('#')?r.color:'var(--role-'+r.color+')';
const warnText=computed(()=>vm.totals.requestedOverloadDays?'An '+vm.compact(vm.totals.requestedOverloadDays)+' Tagen überschreiten geplante Einsätze die Standard-FTE mindestens einer Rolle.':null);
</script>

<template>
  <PfApp :toaster="null" :tooltip="{delayDuration:350}">
    <a class="skip-link" href="#work-surface">Zum Einsatzplan</a>
    <div class="family-window resource-window">
      <nav class="family-ribbon" aria-label="Werkzeuge">
        <button class="ribbon-gem" aria-label="Produktfamilie öffnen" @click="vm.familyOpen=true"><PfIcon name="i-lucide-diamond" /></button>
        <PfTooltip text="Einsatzplan"><PfButton icon="i-lucide-calendar-range" :color="vm.view==='timeline'?'primary':'neutral'" :variant="vm.view==='timeline'?'soft':'ghost'" aria-label="Einsatzplan anzeigen" class="ribbon-tool" @click="vm.setView('timeline')" /></PfTooltip>
        <PfTooltip text="Verknüpfungen"><PfButton icon="i-lucide-link" :color="vm.view==='connections'?'primary':'neutral'" variant="ghost" aria-label="Verknüpfungen anzeigen" class="ribbon-tool" @click="vm.setView('connections')" /></PfTooltip>
        <PfTooltip text="Suchen · Strg K"><PfButton icon="i-lucide-search" color="neutral" variant="ghost" aria-label="Plan durchsuchen" class="ribbon-tool" @click="vm.searchOpen=true" /></PfTooltip>
        <div class="ribbon-space" />
        <PfTooltip text="Berechnung erklären"><PfButton icon="i-lucide-circle-help" color="neutral" variant="ghost" aria-label="Berechnung erklären" class="ribbon-tool" @click="vm.setView('help')" /></PfTooltip>
        <PfTooltip :text="vm.theme==='dark'?'Helles Design':'Dunkles Design'"><PfButton :icon="vm.theme==='dark'?'i-lucide-sun':'i-lucide-moon'" color="neutral" variant="ghost" aria-label="Design wechseln" class="ribbon-tool" @click="vm.toggleTheme" /></PfTooltip>
        <PfTooltip text="Darstellung & Vault"><PfButton icon="i-lucide-settings" color="neutral" variant="ghost" aria-label="Einstellungen öffnen" class="ribbon-tool" @click="vm.setView('settings')" /></PfTooltip>
      </nav>
      <PfDashboardGroup unit="px" :persistent="false" storage-key="resource-atlas-layout" class="family-dashboard">
        <PfDashboardSidebar v-model:collapsed="vm.collapsed" v-model:open="vm.mobileNav" :default-size="214" :min-size="190" :max-size="280" :collapsed-size="0" collapsible :toggle="false" class="family-sidebar" :ui="{header:'family-side-header',body:'family-side-body',footer:'family-side-footer'}">
          <template #header><div class="vault-brand"><PfIcon name="i-lucide-folder" /><span>Product Lab</span><PfBadge color="neutral" variant="subtle" size="xs">LOKAL</PfBadge></div></template>
          <template #default>
            <div class="side-app"><PfIcon name="i-lucide-calendar-range" /><div><strong>Resource Atlas</strong><span>Rollen & Kapazität planen</span></div></div>
            <PfButton color="neutral" variant="outline" icon="i-lucide-search" class="side-search" @click="vm.searchOpen=true">Im Plan suchen <kbd>⌘ K</kbd></PfButton>
            <p class="nav-heading">Planung</p>
            <nav class="editor-nav" aria-label="Planungsansichten">
              <PfButton v-for="item in navigation" :key="item.id" :icon="item.icon" :color="vm.view===item.id?'primary':'neutral'" :variant="vm.view===item.id?'soft':'ghost'" :aria-current="vm.view===item.id?'page':undefined" class="nav-item" @click="vm.setView(item.id)"><span>{{ item.label }}</span><span v-if="item.id==='roles'" class="nav-count">{{ vm.plan.roles.length }}</span></PfButton>
            </nav>
            <div class="plans-heading"><p class="nav-heading">Meine Pläne</p><PfButton icon="i-lucide-plus" variant="ghost" color="neutral" size="xs" aria-label="Neuen Plan erstellen" @click="vm.openPlan(true)" /></div>
            <div class="plan-navigation"><PfButton v-for="p in vm.state.plans" :key="p.id" icon="i-lucide-file-text" :color="p.id===vm.plan.id?'primary':'neutral'" :variant="p.id===vm.plan.id?'soft':'ghost'" class="nav-item" :aria-current="p.id===vm.plan.id?'true':undefined" @click="vm.switchPlan(p.id)"><span>{{ p.name }}</span></PfButton></div>
            <p class="nav-heading family-heading">Produktfamilie</p>
            <PfButton icon="i-lucide-link" :color="vm.view==='connections'?'primary':'neutral'" :variant="vm.view==='connections'?'soft':'ghost'" class="nav-item" @click="vm.setView('connections')"><span>Verknüpfungen</span><span class="nav-count">{{ vm.registry.links.length }}</span></PfButton>
            <PfButton icon="i-lucide-arrow-left-right" :color="vm.view==='files'?'primary':'neutral'" :variant="vm.view==='files'?'soft':'ghost'" class="nav-item" @click="vm.setView('files')">Import & Export</PfButton>
            <div class="side-context"><span class="status-dot" /><div><strong>Eigenständig planen</strong><p>Produktkontext bei Bedarf aus anderen Werkzeugen ergänzen.</p></div></div>
          </template>
          <template #footer><PfIcon name="i-lucide-diamond" /><span>Obsidian Plugin · Prototyp</span></template>
        </PfDashboardSidebar>
        <PfDashboardPanel id="work-surface" class="family-panel" :ui="{body:'family-panel-body resource-panel-body'}">
          <template #header>
            <PfDashboardNavbar :toggle="false" class="family-tabbar">
              <template #left>
                <PfButton :icon="vm.collapsed?'i-lucide-panel-left-open':'i-lucide-panel-left-close'" color="neutral" variant="ghost" aria-label="Seitenleiste umschalten" class="sidebar-toggle-desktop" @click="vm.collapsed=!vm.collapsed" />
                <PfButton icon="i-lucide-panel-left-open" color="neutral" variant="ghost" aria-label="Menü öffnen" class="sidebar-toggle-mobile" @click="vm.mobileNav=true" />
                <div class="workspace-tab"><PfIcon name="i-lucide-calendar-range" /><span>{{ vm.plan.name }}</span></div>
              </template>
              <template #right><span class="tab-motto">Dein Produkt, verbunden.</span><PfBadge size="xs" color="neutral" variant="subtle">OFFLINE</PfBadge></template>
            </PfDashboardNavbar>
            <header class="family-page-header resource-page-header">
              <div class="page-heading"><h1>{{ title }}</h1><p>{{ subtitle }}</p></div>
              <div class="page-actions">
                <div class="history-actions"><PfButton icon="i-lucide-undo-2" color="neutral" variant="ghost" aria-label="Rückgängig" :disabled="!vm.history.length||vm.storageLocked" @click="vm.undo" /><PfButton icon="i-lucide-redo-2" color="neutral" variant="ghost" aria-label="Wiederholen" :disabled="!vm.future.length||vm.storageLocked" @click="vm.redo" /></div>
                <PfButton icon="i-lucide-upload" color="neutral" variant="outline" aria-label="Import" @click="vm.showImport"><span class="action-label">Import</span></PfButton>
                <PfButton icon="i-lucide-download" color="neutral" variant="outline" aria-label="Export" @click="vm.showExport('plan')"><span class="action-label">Export</span></PfButton>
                <PfButton v-if="vm.view==='connections'" icon="i-lucide-plus" class="primary-action" @click="vm.showImport">Kontext importieren</PfButton>
                <PfButton v-else-if="vm.view==='roles'" icon="i-lucide-plus" class="primary-action" @click="vm.openRole()">Rolle hinzufügen</PfButton>
                <PfButton v-else-if="vm.view==='calendar'" icon="i-lucide-plus" class="primary-action" @click="vm.openBlock()">Sperrzeit hinzufügen</PfButton>
                <PfButton v-else icon="i-lucide-plus" class="primary-action" @click="vm.openAllocation()">Einsatz hinzufügen</PfButton>
              </div>
            </header>
            <div v-if="vm.storageError" class="family-warning" role="alert"><PfIcon name="i-lucide-triangle-alert" /><span>{{ vm.storageError }}</span><PfButton v-if="vm.recoveryRaw" size="xs" color="neutral" variant="outline" @click="vm.download('resource-atlas-originaldaten.json',vm.recoveryRaw)">Sicherung herunterladen</PfButton><PfButton v-if="vm.storageLocked" size="xs" color="neutral" variant="outline" @click="vm.recover">{{ vm.otherTab?'Neueren Stand laden':'Neu beginnen' }}</PfButton><PfButton v-else size="xs" color="neutral" variant="outline" @click="vm.showExport('workspace')">Alle Pläne exportieren</PfButton></div>
          </template>

          <template #body>
            <div class="resource-body" :class="{'has-inspector':!!vm.draft}">
              <main class="resource-main">
                <section v-show="vm.view==='timeline'" class="planning-workspace">
                  <div class="plan-context">
                    <div class="plan-selection"><label class="visually-hidden" for="active-plan">Aktiver Plan</label><PfSelect id="active-plan" :model-value="vm.state.activePlanId" :items="vm.planOptions" @update:model-value="vm.switchPlan" /><PfButton icon="i-lucide-pencil" color="neutral" variant="ghost" aria-label="Plan bearbeiten" @click="vm.openPlan()" /></div>
                    <button class="plan-dates" @click="vm.openPlan()"><PfIcon name="i-lucide-calendar" /><span>{{ vm.dateLabel(vm.plan.start) }} <span class="date-to">bis</span> {{ vm.dateLabel(vm.plan.end) }}</span></button>
                    <PfButton icon="i-lucide-plus" color="neutral" variant="ghost" size="xs" class="new-plan-compact" @click="vm.openPlan(true)">Neuer Plan</PfButton>
                  </div>
                  <div class="effort-ledger">
                    <div class="planned-effort"><strong data-testid="total-pt">{{ vm.number(vm.totals.netPt) }} <span>PT</span></strong><div>Geplanter Aufwand<small>{{ vm.compact(vm.totals.hours) }} Stunden · {{ vm.plan.roles.length }} Rollen</small></div></div>
                    <div class="budget-ledger"><div><span>Budget</span><button @click="vm.openPlan()">{{ vm.plan.budgetPt===null?'Festlegen':vm.number(vm.plan.budgetPt)+' PT' }}<PfIcon name="i-lucide-pencil" /></button></div><div v-if="vm.plan.budgetPt!==null" :class="vm.totals.budgetExceededPt>0?'budget-over':'budget-within'"><span>{{ vm.totals.budgetExceededPt>0?'Über Budget':'Noch verfügbar' }}</span><strong>{{ vm.totals.budgetExceededPt>0?'+':'' }}{{ vm.number(vm.totals.budgetExceededPt>0?vm.totals.budgetExceededPt:vm.totals.budgetRemainingPt) }} PT</strong></div></div>
                    <button class="calendar-ledger" @click="vm.setView('calendar')"><PfIcon name="i-lucide-calendar-days" /><span>{{ vm.compact(vm.totals.workingDays) }} Arbeitstage<small>{{ vm.compact(vm.totals.blockedDays) }} Tage planweit gesperrt</small></span><PfIcon name="i-lucide-chevron-right" /></button>
                  </div>
                  <div class="timeline-toolbar">
                    <div class="tool-segment" role="group" aria-label="Timeline-Werkzeug"><PfTooltip text="Auswählen und verschieben"><PfButton icon="i-lucide-mouse-pointer-2" :variant="vm.tool==='select'?'soft':'ghost'" :color="vm.tool==='select'?'primary':'neutral'" aria-label="Auswählen" :aria-pressed="vm.tool==='select'" @click="vm.tool='select'" /></PfTooltip><PfButton icon="i-lucide-plus" :variant="vm.tool==='allocate'?'soft':'ghost'" :color="vm.tool==='allocate'?'primary':'neutral'" :aria-pressed="vm.tool==='allocate'" @click="vm.tool='allocate'">Einsatz zeichnen</PfButton><PfButton icon="i-lucide-ban" :variant="vm.tool==='block'?'soft':'ghost'" :color="vm.tool==='block'?'primary':'neutral'" :aria-pressed="vm.tool==='block'" @click="vm.tool='block'">Sperrzeit</PfButton></div>
                    <div class="timeline-view-tools"><label class="visually-hidden" for="timeline-scale">Zeitmaßstab</label><PfSelect id="timeline-scale" v-model="vm.granularity" :items="[{label:'Tage',value:'day'},{label:'Wochen',value:'week'},{label:'Monate',value:'month'}]" /><PfTooltip :text="vm.fit?'Detailansicht':'Gesamten Plan einpassen'"><PfButton icon="i-lucide-maximize" :variant="vm.fit?'soft':'ghost'" :color="vm.fit?'primary':'neutral'" :aria-pressed="vm.fit" aria-label="Gesamten Plan einpassen" @click="vm.fit=!vm.fit" /></PfTooltip></div>
                  </div>
                  <div v-if="warnText" class="schedule-warning" role="status"><PfIcon name="i-lucide-triangle-alert" /><span>{{ warnText }}</span><PfButton size="xs" variant="ghost" color="warning" @click="vm.setView('roles')">Prüfen</PfButton></div>
                  <Timeline :plan="vm.plan" :calculation="vm.calculation" :granularity="vm.granularity" :fit="vm.fit" :tool="vm.tool" :selected-id="vm.selectedId" @select-allocation="vm.openAllocation" @edit-role="vm.openRole" @new-role="vm.openRole()" @create-allocation="range=>{vm.openAllocation(null,range);vm.tool='select'}" @create-block="range=>{vm.openBlock(null,range);vm.tool='select'}" @update-allocation="vm.moveAllocation" @select-block="vm.openBlock" />
                  <footer class="timeline-footnote"><div><span class="legend-dot allocation-dot" />Einsatz<span class="legend-dot closure-dot" />Sperrzeit<span class="legend-dot weekend-dot" />Arbeitsfrei</div><span v-if="vm.tool==='select'">Balken verschieben · Ränder ziehen · Doppelklick für neuen Einsatz</span><span v-else>Zeitraum in einer Zeile aufziehen · danach FTE und Details festlegen</span><button @click="vm.setView('help')">1 FTE × 1 Arbeitstag = 1 PT<PfIcon name="i-lucide-info" /></button></footer>
                </section>

                <section v-if="vm.view==='roles'" class="resource-page role-page">
                  <div class="section-heading"><div><h2>{{ vm.plan.name }}</h2><p>{{ vm.dateLabel(vm.plan.start) }} – {{ vm.dateLabel(vm.plan.end) }} · alle Einsatzzeiträume</p></div><PfInput v-model="vm.roleQuery" icon="i-lucide-search" placeholder="Rolle suchen…" aria-label="Rollen filtern" /></div>
                  <div v-if="!vm.plan.roles.length" class="resource-empty"><PfIcon name="i-lucide-users" /><h3>Welche Rollen braucht dein Plan?</h3><p>Lege eine Rolle und ihre Standard-FTE an. Plane anschließend die Zeiträume, in denen sie benötigt wird.</p><PfButton icon="i-lucide-plus" @click="vm.openRole()">Erste Rolle anlegen</PfButton></div>
                  <div v-else class="resource-table-wrap"><table class="resource-table roles-table"><thead><tr><th>Rolle</th><th class="numeric">Geplant</th><th class="numeric">Standard-FTE</th><th class="numeric">Einsätze</th><th class="numeric">Vor Sperrzeiten</th><th class="numeric">Entfällt</th><th>Kapazität</th><th><span class="visually-hidden">Aktionen</span></th></tr></thead><tbody><tr v-for="r in vm.filteredRoles" :key="r.id"><td><button class="role-name-button" @click="vm.openRole(r.id)"><span class="role-swatch" :style="{background:roleColor(r)}" /><strong>{{ r.name }}</strong></button><small v-if="r.requestedOverloadDays" class="text-warning">{{ r.requestedOverloadDays }} Tage über Standard-FTE</small></td><td class="numeric strong-cell" :data-testid="'summary-total-'+r.id">{{ vm.number(r.netPt) }} PT</td><td class="numeric">{{ vm.compact(r.fte) }}</td><td class="numeric">{{ r.allocationCount }}</td><td class="numeric">{{ vm.number(r.grossPt) }} PT</td><td class="numeric">{{ vm.number(r.blockedPt) }} PT</td><td><div class="capacity-track"><span :style="{width:Math.min(100,r.capacityPt?r.netPt/r.capacityPt*100:0)+'%',background:roleColor(r)}" /></div><small>{{ vm.number(r.netPt) }} / {{ vm.number(r.capacityPt) }} PT</small></td><td><div class="row-actions"><PfTooltip text="Einsatz für diese Rolle"><PfButton icon="i-lucide-plus" color="neutral" variant="ghost" :aria-label="'Einsatz für '+r.name+' hinzufügen'" @click="vm.openAllocation(null,{roleId:r.id})" /></PfTooltip><PfTooltip text="Rolle bearbeiten"><PfButton icon="i-lucide-pencil" color="neutral" variant="ghost" :aria-label="r.name+' bearbeiten'" @click="vm.openRole(r.id)" /></PfTooltip></div></td></tr><tr v-if="!vm.filteredRoles.length"><td colspan="8" class="table-empty">Keine Rolle passt zu deiner Suche.</td></tr></tbody><tfoot><tr><th>Gesamter Plan</th><td class="numeric">{{ vm.number(vm.totals.netPt) }} PT</td><td class="numeric">{{ vm.compact(vm.plan.roles.reduce((s,r)=>s+r.fte,0)) }}</td><td class="numeric">{{ vm.plan.allocations.length }}</td><td class="numeric">{{ vm.number(vm.totals.grossPt) }} PT</td><td class="numeric">{{ vm.number(vm.totals.blockedPt) }} PT</td><td colspan="2">{{ vm.number(vm.totals.capacityPt) }} PT verfügbar</td></tr></tfoot></table></div>
                  <p class="explanation-note"><PfIcon name="i-lucide-info" /><span>Standard-FTE sind Kapazität und Vorgabe für neue Einsätze. Nur eingeplante Zeiträume erzeugen Aufwand. Die verfügbare Kapazität umfasst die gesamte Laufzeit abzüglich arbeitsfreier Tage und Sperrzeiten.</span></p>
                  <div class="section-heading lower-heading"><div><h3>Einzelne Einsatzzeiträume</h3><p>Zeiträume lassen sich unabhängig bearbeiten, aufteilen oder duplizieren.</p></div><PfButton icon="i-lucide-download" variant="outline" color="neutral" @click="vm.showExport('roles')">Rollenübersicht exportieren</PfButton></div>
                  <div class="allocation-list"><button v-for="a in vm.plan.allocations" :key="a.id" class="allocation-list-row" @click="vm.openAllocation(a.id)"><span class="role-swatch" :style="{background:roleColor(vm.plan.roles.find(r=>r.id===a.roleId))}" /><span><strong>{{ a.name||'Einsatz' }}</strong><small>{{ vm.plan.roles.find(r=>r.id===a.roleId)?.name }} · {{ vm.dateLabel(a.start,false) }}–{{ vm.dateLabel(a.end) }}</small></span><span>{{ vm.compact(a.fte) }} FTE</span><strong>{{ vm.number(vm.calculation.allocations.find(c=>c.id===a.id)?.netPt) }} PT</strong><PfIcon name="i-lucide-chevron-right" /></button></div>
                </section>

                <section v-if="vm.view==='analysis'" class="resource-page">
                  <div class="section-heading"><div><h2>Wann wird wie viel Aufwand geplant?</h2><p>{{ vm.number(vm.totals.netPt) }} PT über {{ vm.compact(vm.totals.calendarDays) }} Kalendertage</p></div><PfSelect v-model="vm.analysisMode" aria-label="Auswertungszeitraum" :items="[{label:'Kalenderwochen',value:'week'},{label:'Monate',value:'month'}]" /></div>
                  <div class="effort-chart" role="group" aria-label="Geplante Personentage je Zeitraum"><div class="chart-bars"><button v-for="bucket in vm.periods" :key="bucket.key" class="chart-column" :title="bucket.label+': '+vm.number(bucket.netPt)+' PT'" @click="vm.notify(bucket.label+' · '+vm.dateLabel(bucket.start,false)+'–'+vm.dateLabel(bucket.end)+' · '+vm.number(bucket.netPt)+' PT')"><span class="chart-value">{{ vm.compact(bucket.netPt) }}</span><span class="chart-bar-space"><span class="chart-bar" :style="{height:Math.max(bucket.netPt?2:0,bucket.netPt/vm.maxPeriod*100)+'%'}" /></span><span class="chart-label">{{ vm.analysisMode==='week'?bucket.label.split(' · ')[0]:bucket.label }}</span></button></div><div class="chart-caption"><span>Personentage · Summen aus taggenauer Berechnung</span><PfButton icon="i-lucide-download" variant="ghost" color="neutral" size="xs" @click="vm.showExport('weeks')">Wochen-CSV</PfButton></div></div>
                  <div class="resource-table-wrap"><table class="resource-table period-table"><caption>Aufwand je Rolle und Zeitraum, in Personentagen</caption><thead><tr><th>Zeitraum</th><th class="numeric">Arbeitstage</th><th v-for="r in vm.plan.roles" :key="r.id" class="numeric">{{ r.name }}</th><th class="numeric">Gesamt</th></tr></thead><tbody><tr v-for="bucket in vm.periods" :key="bucket.key"><th>{{ bucket.label }}<small>{{ vm.dateLabel(bucket.start,false) }}–{{ vm.dateLabel(bucket.end,false) }}</small></th><td class="numeric">{{ bucket.workingDays }}</td><td v-for="r in vm.plan.roles" :key="r.id" class="numeric" :class="{'muted-cell':!bucket.roles.find(x=>x.roleId===r.id)?.netPt}">{{ vm.number(bucket.roles.find(x=>x.roleId===r.id)?.netPt) }}</td><td class="numeric strong-cell">{{ vm.number(bucket.netPt) }}</td></tr></tbody><tfoot><tr><th>Gesamt</th><td class="numeric">{{ vm.totals.workingDays }}</td><td v-for="r in vm.calculation.roles" :key="r.id" class="numeric">{{ vm.number(r.netPt) }}</td><td class="numeric">{{ vm.number(vm.totals.netPt) }} PT</td></tr></tfoot></table></div>
                  <p class="explanation-note"><PfIcon name="i-lucide-info" /><span>Randwochen und Monate folgen den tatsächlichen Daten. Ein Monat wird nicht pauschal als vier Wochen gerechnet. Die Summen entstehen vor der Rundung der Anzeige.</span></p>
                </section>

                <section v-if="vm.view==='calendar'" class="resource-page calendar-page">
                  <div class="section-heading"><div><h2>Dein Plankalender</h2><p>{{ vm.dateLabel(vm.plan.start) }} – {{ vm.dateLabel(vm.plan.end) }} · Start und Ende eingeschlossen</p></div><PfButton icon="i-lucide-pencil" color="neutral" variant="outline" @click="vm.openCalendar">Kalender bearbeiten</PfButton></div>
                  <div class="calendar-settings-strip"><div><span>Arbeitstage</span><div class="weekday-chips"><span v-for="day in [1,2,3,4,5,6,7]" :key="day" :class="{active:vm.plan.calendar.workdays.includes(day)}">{{ vm.DAY_NAMES[day] }}</span></div></div><div><span>Ein Personentag</span><strong>{{ vm.compact(vm.plan.calendar.hoursPerDay) }} Stunden</strong></div><div><span>Arbeitstage im Zeitraum</span><strong>{{ vm.compact(vm.totals.workingDays) }}</strong></div><div><span>Planweit verfügbar</span><strong>{{ vm.compact(vm.totals.availableDays) }} Tage</strong></div></div>
                  <div class="section-heading lower-heading"><div><h3>Sperrzeiten</h3><p>Betriebsferien, Urlaub oder andere Zeit, die nicht für diesen Plan zur Verfügung steht.</p></div><PfButton icon="i-lucide-plus" color="neutral" variant="outline" @click="vm.openBlock()">Sperrzeit anlegen</PfButton></div>
                  <div v-if="!vm.plan.blocks.length" class="inline-empty">Noch keine Sperrzeiten. Eine planweite Sperre gilt für alle Rollen.</div>
                  <div class="calendar-records"><button v-for="block in vm.plan.blocks" :key="block.id" class="calendar-record" @click="vm.openBlock(block.id)"><span class="calendar-record-icon"><PfIcon :name="block.roleId?'i-lucide-user-round':'i-lucide-calendar-off'" /></span><span><strong>{{ block.name||'Sperrzeit' }}</strong><small>{{ block.roleId?vm.plan.roles.find(r=>r.id===block.roleId)?.name:'Alle Rollen' }} · {{ vm.dateLabel(block.start) }}–{{ vm.dateLabel(block.end) }}</small></span><PfBadge :color="block.fraction===1?'neutral':'warning'" variant="subtle">{{ vm.compact(block.fraction*100) }} % gesperrt</PfBadge><PfIcon name="i-lucide-pencil" /></button></div>
                  <div class="section-heading lower-heading"><div><h3>Feiertage & einzelne arbeitsfreie Tage</h3><p>Feiertage werden berücksichtigt, wenn du sie hier einträgst. Es ist kein regionaler Feiertagskalender voreingestellt.</p></div><PfButton icon="i-lucide-plus" color="neutral" variant="outline" @click="vm.openHoliday()">Tag hinzufügen</PfButton></div>
                  <div v-if="!vm.plan.calendar.holidays.length" class="inline-empty">Keine zusätzlichen arbeitsfreien Tage eingetragen.</div>
                  <div class="calendar-records"><button v-for="holiday in vm.plan.calendar.holidays" :key="holiday.id" class="calendar-record" @click="vm.openHoliday(holiday.id)"><span class="calendar-record-icon"><PfIcon name="i-lucide-calendar" /></span><span><strong>{{ holiday.name }}</strong><small>{{ vm.dateLabel(holiday.date) }}</small></span><PfIcon name="i-lucide-pencil" /></button></div>
                  <p class="explanation-note"><PfIcon name="i-lucide-info" /><span>Treffen mehrere Sperren auf denselben Tag und dieselbe Rolle, zählt der höchste gesperrte Anteil. Eine vollständige planweite Sperre und ein Urlaubstag werden also nicht doppelt abgezogen.</span></p>
                </section>

                <section v-if="vm.view==='connections'" class="resource-connections">
                  <div class="connection-toolbar"><PfInput v-model="vm.referenceQuery" icon="i-lucide-search" aria-label="Importierten Kontext suchen" placeholder="Kontext suchen…" class="catalog-search" /><span>{{ vm.registry.records.length }} Snapshots · {{ vm.registry.links.length }} Verknüpfungen</span></div>
                  <div v-if="!vm.registry.records.length" class="resource-empty"><PfIcon name="i-lucide-link" /><h2>Mit deinem Produktkontext verbinden</h2><p>Importiere ein Familienpaket aus Storyloom, Component Atlas, Sitemap Atlas oder Dissect. Verknüpfe eine Rolle oder einen Einsatz mit dem passenden Datensatz.</p><PfButton icon="i-lucide-upload" @click="vm.showImport">Familienpaket importieren</PfButton><small>Story Points und Komponenten werden nicht automatisch in Personentage umgerechnet.</small></div>
                  <div v-else class="resource-connection-layout"><div class="resource-reference-list"><button v-for="record in vm.externalRecords" :key="record.ref" class="resource-reference" :class="{selected:vm.selectedEntity?.ref===record.ref}" @click="vm.selectedReference=record.ref"><PfIcon :name="vm.APPS[record.source.appId]?.icon||'i-lucide-file-text'" /><span><strong>{{ record.title }}</strong><small>{{ vm.sourceName(record.source.appId) }} · {{ record.kind }}</small></span><PfBadge v-if="record.missing" color="warning" variant="subtle">Fehlt</PfBadge></button><p v-if="!vm.externalRecords.length" class="inline-empty">Keine passenden Datensätze.</p></div><aside v-if="vm.selectedEntity" class="reference-inspector"><div class="source-line">{{ vm.sourceName(vm.selectedEntity.source.appId) }}<PfBadge color="neutral" variant="subtle">Snapshot</PfBadge></div><h2>{{ vm.selectedEntity.title }}</h2><p>{{ vm.selectedEntity.summary }}</p><dl><dt>Quell-Workspace</dt><dd>{{ vm.selectedEntity.source.workspaceTitle }}</dd><dt>Datensatz</dt><dd>{{ vm.selectedEntity.kind }}</dd><dt>Status</dt><dd>{{ vm.selectedEntity.missing?'Im letzten vollständigen Quellpaket nicht enthalten':'Quellsnapshot vorhanden' }}</dd></dl><label class="field-label" for="connection-local">Verknüpfen mit</label><PfSelect id="connection-local" v-model="vm.linkTarget" :items="[{label:'Aktueller Ressourcenplan',value:'plan'},...vm.localLinkOptions]" class="full-input" /><label class="field-label" for="connection-relation">Beziehung</label><PfSelect id="connection-relation" v-model="vm.linkRelation" :items="[{label:'Steht in Beziehung zu',value:'relates-to'},{label:'Unterstützt Umsetzung',value:'supports-story'},{label:'Plant Aufwand für',value:'plans-effort-for'}]" class="full-input" /><PfButton icon="i-lucide-link" class="link-submit" @click="vm.addLink">Verknüpfung anlegen</PfButton><div class="detail-section-title"><h3>Verknüpft mit</h3><span>{{ vm.currentLinks.length }}</span></div><div v-for="link in vm.currentLinks" :key="link.id" class="connection-card"><div><small>{{ link.relation }}</small><strong>{{ vm.endpoint(link) }}</strong></div><PfButton icon="i-lucide-unlink" color="neutral" variant="ghost" :aria-label="'Verknüpfung zu '+vm.endpoint(link)+' entfernen'" @click="vm.removeLink(link)" /></div><p v-if="!vm.currentLinks.length" class="quiet-empty">Dieser Snapshot ist noch nicht verknüpft.</p><p v-if="vm.linkAttention" class="text-warning">{{ vm.linkAttention }} Verknüpfungen im Plan benötigen eine Prüfung.</p></aside></div>
                </section>

                <section v-if="vm.view==='files'" class="resource-page files-page">
                  <div class="section-heading"><div><h2>Ein Plan. Mehrere passende Formate.</h2><p>Wähle den Export nach dem nächsten Arbeitsschritt.</p></div><PfButton icon="i-lucide-upload" variant="outline" color="neutral" @click="vm.showImport">Datei importieren</PfButton></div>
                  <div class="export-options">
                    <button @click="vm.showExport('plan')"><PfIcon name="i-lucide-file-json" /><span><strong>Plan sichern oder weitergeben</strong><small>Vollständiges JSON mit Rollen, Einsätzen, Sperrzeiten und Kalender.</small></span><PfIcon name="i-lucide-arrow-up-right" /></button>
                    <button @click="vm.showExport('markdown')"><PfIcon name="i-lucide-file-text" /><span><strong>Im Obsidian-Vault ablegen</strong><small>Markdown mit Frontmatter, Aufwandstabellen und vollständigen Wiederherstellungsdaten.</small></span><PfIcon name="i-lucide-arrow-up-right" /></button>
                    <button @click="vm.showExport('roles')"><PfIcon name="i-lucide-table-2" /><span><strong>Aufwand als Tabelle auswerten</strong><small>Rollen-, Wochen- oder Tagesdaten als CSV mit Dezimalkomma.</small></span><PfIcon name="i-lucide-arrow-up-right" /></button>
                    <button @click="vm.showExport('family')"><PfIcon name="i-lucide-link" /><span><strong>Mit der Produktfamilie austauschen</strong><small>Ressourcenplan, externe Snapshots und Verknüpfungen in einem Familienpaket.</small></span><PfIcon name="i-lucide-arrow-up-right" /></button>
                    <button @click="vm.showExport('workspace')"><PfIcon name="i-lucide-folder" /><span><strong>Alle Pläne sichern</strong><small>{{ vm.state.plans.length }} native Pläne in einer JSON-Datei. Familienpakete enthalten zusätzlich die Verknüpfungen je Plan.</small></span><PfIcon name="i-lucide-arrow-up-right" /></button>
                  </div>
                  <p class="explanation-note"><PfIcon name="i-lucide-info" /><span>Der Prototyp speichert lokal im Browser. Exportierte Dateien legst du selbst in deinem Vault ab. Eine JSON- oder Resource-Atlas-Markdown-Datei kann wieder importiert werden; CSV ist eine Auswertung.</span></p>
                </section>

                <section v-if="vm.view==='help'" class="resource-page help-page">
                  <h2>Von FTE zu Personentagen</h2><p class="help-intro">Ein Einsatz verbindet eine Rolle, einen Zeitraum und die benötigten FTE. Der Plan rechnet jeden Kalendertag einzeln und summiert den Aufwand.</p>
                  <div class="formula-panel"><span>Pro Arbeitstag</span><strong>Einsatz-FTE × verfügbarer Anteil = Personentage</strong><p>1 FTE für 5 Arbeitstage = 5 PT. 0,2 FTE für 5 Arbeitstage = 1 PT.</p></div>
                  <div class="help-steps"><article><PfIcon name="i-lucide-calendar-range" /><div><h3>Zeitraum festlegen</h3><p>Start- und Endtag zählen mit. Der Arbeitskalender bestimmt, welche Wochentage und Feiertage arbeitsfrei sind. Wochen und Monate richten sich nach den tatsächlichen Daten.</p></div></article><article><PfIcon name="i-lucide-users" /><div><h3>Rollen und Einsätze planen</h3><p>Standard-FTE beschreiben die Kapazität einer Rolle und füllen neue Einsätze vor. Jeder Einsatz darf eigene FTE haben. Zwischen den Einsätzen entsteht kein Aufwand. Überlappende Einsätze werden addiert; Überschreitungen bleiben sichtbar.</p></div></article><article><PfIcon name="i-lucide-ban" /><div><h3>Zeit sperren</h3><p>Eine Sperre kann für alle Rollen oder eine einzelne Rolle gelten. Bei 100 % entsteht an den betroffenen Arbeitstagen kein Aufwand. 50 % halbieren ihn. Überlappende Sperren verwenden den höchsten Anteil, ohne ihn doppelt abzuziehen.</p></div></article><article><PfIcon name="i-lucide-chart-column" /><div><h3>Personentage und Budget prüfen</h3><p>Der Plan summiert zuerst präzise Tageswerte und rundet nur die Anzeige. Stunden ergeben sich aus PT × {{ vm.compact(vm.plan.calendar.hoursPerDay) }}. Ein PT ist hier ein konfigurierbarer voller Arbeitstag, keine feste gesetzliche Stundenanzahl.</p></div></article></div>
                  <div class="help-example"><h3>Das Rechenbeispiel nachvollziehen</h3><p>UX: 25 + 10 = 35 PT. Requirements Engineering: 35 PT. Entwicklung: 45 + 35 = 80 PT. Delivery Management: 0,2 × 70 Arbeitstage = 14 PT.</p><strong>164 PT geplant · 150 PT Budget · 14 PT über Budget</strong><p>Die Betriebsferien liegen zwischen den Einsätzen. Sie reduzieren die verfügbare Gesamtkapazität; die vorhandenen Beispielbalken verlieren dadurch keinen Aufwand.</p></div>
                  <div class="keyboard-guide"><span><kbd>Strg / ⌘ K</kbd>Suchen</span><span><kbd>Strg / ⌘ Z</kbd>Rückgängig</span><span><kbd>← / →</kbd>Fokussierten Balken verschieben</span><span><kbd>Shift</kbd>In 7-Tage-Schritten</span></div>
                </section>

                <section v-if="vm.view==='settings'" class="resource-page settings-page">
                  <h2>Darstellung & Ablage</h2>
                  <div class="preference-row"><div><h3>Design</h3><p>Die gemeinsame Darstellung der Produktfamilie, in hell oder dunkel.</p></div><PfButton :icon="vm.theme==='dark'?'i-lucide-sun':'i-lucide-moon'" color="neutral" variant="outline" @click="vm.toggleTheme">{{ vm.theme==='dark'?'Helles Design verwenden':'Dunkles Design verwenden' }}</PfButton></div>
                  <div class="preference-row"><div><h3>Ordner für Ressourcenpläne</h3><p>Relativer Zielordner im Vault. Der Markdown-Export nennt diesen Pfad; er schreibt nicht automatisch in deinen Vault.</p></div><div class="folder-preference"><PfInput v-model="vm.folderInput" aria-label="Vault-Ordner" /><PfButton @click="vm.saveFolder">Speichern</PfButton></div></div>
                  <div class="preference-row"><div><h3>Aktuellen Plan kopieren</h3><p>Eine unabhängige Variante mit eigener Plan-ID erstellen. Externe Verknüpfungen werden nicht mitkopiert.</p></div><PfButton icon="i-lucide-copy" color="neutral" variant="outline" @click="vm.duplicatePlan">Plan duplizieren</PfButton></div>
                  <div class="preference-row"><div><h3>Lokalen Arbeitsstand sichern</h3><p>Browserdaten gehören zu diesem Browser und Speicherort. Sichere die Pläne für den Wechsel auf ein anderes Gerät.</p></div><PfButton icon="i-lucide-download" color="neutral" variant="outline" @click="vm.showExport('workspace')">Alle Pläne exportieren</PfButton></div>
                  <p class="build-note"><PfIcon name="i-lucide-info" /><span>Resource Atlas · eigenständiger Obsidian-Plugin-Prototyp<br><span>Rollen und geplanter Aufwand; keine Personenverwaltung oder Ist-Zeiterfassung.</span></span></p>
                </section>
              </main>
              <Inspector v-if="vm.draft" :draft="vm.draft" :plan="vm.plan" :calculation="vm.calculation" :error="vm.formError" :preview="vm.draftPreview" :dirty="!!vm.dirty" @change="vm.changeDraft" @save="vm.saveDraft" @close="vm.closeInspector" @delete="vm.deleteDraft" @duplicate="vm.duplicateDraft" @move="vm.moveDraft" />
            </div>
          </template>
          <template #footer><div class="family-statusbar"><span>Resource Atlas</span><span class="status-records">{{ vm.plan.roles.length }} Rollen · {{ vm.plan.allocations.length }} Einsätze · {{ vm.registry.links.length }} Verknüpfungen</span><span class="save-indicator"><i class="status-dot" :class="{warning:vm.storageError||vm.dirty}" />{{ vm.storageError?'Speicherhinweis beachten':vm.dirty?'Ungespeicherte Eingaben':'Im Browser gespeichert' }}</span><span class="status-prototype">1 PT = {{ vm.compact(vm.plan.calendar.hoursPerDay) }} Std.</span></div></template>
        </PfDashboardPanel>
      </PfDashboardGroup>
    </div>

    <div v-if="vm.notice" class="resource-notice" :class="{error:vm.noticeError}" :role="vm.noticeError?'alert':'status'"><PfIcon :name="vm.noticeError?'i-lucide-triangle-alert':'i-lucide-check'" /><span>{{ vm.notice }}</span><button aria-label="Hinweis schließen" @click="vm.notice=''"><PfIcon name="i-lucide-x" /></button></div>
    <PfModal v-model:open="vm.confirmOpen" :title="vm.confirmation.title" :description="vm.confirmation.description" :ui="{content:'family-modal resource-modal'}"><template #footer><PfButton color="neutral" variant="ghost" @click="vm.confirmOpen=false">Abbrechen</PfButton><PfButton :color="vm.confirmation.danger?'error':'primary'" @click="vm.confirm">{{ vm.confirmation.label }}</PfButton></template></PfModal>
    <PfModal v-model:open="vm.searchOpen" title="Im Plan suchen" description="Rollen, Einsatzzeiträume und Sperrzeiten schnell öffnen." :ui="{content:'family-modal resource-modal'}"><template #body><PfInput v-model="vm.searchText" autofocus icon="i-lucide-search" placeholder="Name, Rolle oder Zeitraum…" aria-label="Suchbegriff" class="full-input" /><div class="search-results"><button v-for="result in vm.searchResults" :key="result.kind+result.id" @click="vm.reveal(result)"><PfIcon :name="result.kind==='role'?'i-lucide-users':result.kind==='block'?'i-lucide-ban':'i-lucide-calendar-range'" /><span><strong>{{ result.title }}</strong><small>{{ result.subtitle }}</small></span><PfIcon name="i-lucide-arrow-right" /></button><p v-if="!vm.searchResults.length" class="inline-empty">Keine passenden Einträge.</p></div></template></PfModal>

    <PfModal v-model:open="vm.importOpen" title="Plan oder Kontext importieren" description="Die Vorschau verändert noch keine Daten. Prüfe die Quelle, bevor du sie übernimmst." :ui="{content:'family-modal resource-modal import-modal'}">
      <template #body>
        <input type="file" accept=".json,.md,.markdown,application/json,text/markdown" class="visually-hidden" aria-label="Importdatei auswählen" @change="vm.chooseFile" />
        <div class="import-file-row"><PfButton icon="i-lucide-upload" color="neutral" variant="outline" @click="$event.currentTarget.closest('[role=dialog]').querySelector('input[type=file]').click()">Datei auswählen</PfButton><span>Resource Atlas JSON · Markdown · Familienpaket · bis 32 MB</span></div>
        <label for="import-text" class="field-label">Oder Inhalt einfügen</label><PfTextarea id="import-text" v-model="vm.importText" :rows="4" :autoresize="false" :spellcheck="false" wrap="off" class="full-input mono" placeholder="JSON oder exportierte Resource-Atlas-Notiz…" @paste="vm.pasteImport" @update:model-value="vm.staged=null;vm.importError=''" />
        <PfButton v-if="!vm.staged" :disabled="!vm.importText.trim()" variant="outline" color="neutral" class="review-button" @click="vm.stageImport(vm.importText)">Import prüfen</PfButton>
        <p v-if="vm.importError" class="inline-warning" role="alert">{{ vm.importError }}</p>
        <template v-if="vm.staged?.kind==='family'"><div class="import-source"><PfIcon :name="vm.APPS[vm.staged.package.source.appId]?.icon||'i-lucide-package'" /><div><strong>{{ vm.staged.package.source.workspaceTitle }}</strong><span>{{ vm.sourceName(vm.staged.package.source.appId) }} · Familienpaket</span></div></div><div class="import-review-line"><span><strong>{{ vm.importFamilySummary.added }}</strong> neue Datensätze</span><span><strong>{{ vm.importFamilySummary.changed }}</strong> Änderungen</span><span><strong>{{ vm.importFamilySummary.links }}</strong> Verknüpfungen</span></div><PfCheckbox v-model="vm.updateSnapshots" label="Vorhandene Snapshots aktualisieren" description="Ohne Auswahl bleiben vorhandene Versionen erhalten. Eigene Plandaten werden nicht überschrieben." /><div v-if="vm.familyRestorable" class="native-restore-options"><label for="family-import-mode" class="field-label">Verwendung</label><PfSelect id="family-import-mode" v-model="vm.importMode" :items="[{label:'Nur als externen Kontext importieren',value:'merge'},{label:'Nativen Ressourcenplan wiederherstellen',value:'restore'}]" class="full-input" /><PfCheckbox v-if="vm.importMode==='restore'" v-model="vm.overwrite" label="Einen vorhandenen Plan mit derselben ID ersetzen" description="Plan und Verbindungskontext werden zusammen übernommen. Rückgängig bleibt verfügbar." /></div></template>
        <template v-else-if="vm.staged"><div class="native-preview-plans"><div v-for="p in previewPlans" :key="p.id"><PfIcon name="i-lucide-calendar-range" /><span><strong>{{ p.name }}</strong><small>{{ vm.dateLabel(p.start) }}–{{ vm.dateLabel(p.end) }} · {{ p.roles }} Rollen · {{ p.allocations }} Einsätze</small></span></div></div><label for="native-import-mode" class="field-label">Pläne übernehmen</label><PfSelect id="native-import-mode" v-model="vm.importMode" :items="[{label:'Identitäten erhalten',value:'merge'},{label:'Als unabhängige Kopien importieren',value:'copy'}]" class="full-input" /><PfCheckbox v-if="vm.importConflicts.length&&vm.importMode==='merge'" v-model="vm.overwrite" :label="vm.importConflicts.length+' vorhandene Pläne mit gleicher ID ersetzen'" description="Die übrigen Pläne bleiben erhalten. Rückgängig stellt den vorherigen Stand wieder her." /><p v-else class="field-hint">Neue Pläne werden hinzugefügt. Ihre Rollen, Einsätze, Sperrzeiten und Kalender bleiben vollständig erhalten.</p></template>
      </template>
      <template #footer><PfButton color="neutral" variant="ghost" @click="vm.importOpen=false">Abbrechen</PfButton><PfButton :disabled="!vm.staged||(vm.staged.kind!=='family'&&vm.importConflicts.length&&vm.importMode==='merge'&&!vm.overwrite)" @click="vm.applyImport">{{ vm.staged?.kind==='family'?(vm.importMode==='restore'?'Plan wiederherstellen':'Kontext importieren'):'Pläne importieren' }}</PfButton></template>
    </PfModal>

    <PfModal v-model:open="vm.exportOpen" title="Plan exportieren" description="Eine portable Datei für Sicherung, Obsidian oder die nächste Auswertung." :ui="{content:'family-modal resource-modal export-modal'}">
      <template #body><label class="field-label" for="export-format">Format</label><PfSelect id="export-format" v-model="vm.exportType" :items="vm.exportFormats" class="full-input" /><p v-if="vm.exportData.error||vm.exportError" class="inline-warning" role="alert">{{ vm.exportData.error||vm.exportError }}</p><template v-if="!vm.exportData.error"><div class="export-summary"><PfIcon name="i-lucide-file-down" /><div><strong>{{ vm.exportData.filename }}</strong><span>{{ vm.number(vm.totals.netPt) }} PT · {{ vm.plan.roles.length }} Rollen · {{ vm.plan.allocations.length }} Einsätze</span></div></div><p class="field-hint">{{ vm.exportData.hint }}</p><details class="export-preview"><summary>Dateiinhalt ansehen</summary><pre tabindex="0">{{ vm.exportData.text }}</pre></details></template></template>
      <template #footer><PfButton color="neutral" variant="ghost" @click="vm.exportOpen=false">Schließen</PfButton><PfButton color="neutral" variant="outline" :disabled="!!vm.exportData.error" @click="vm.copyExport">Kopieren</PfButton><PfButton icon="i-lucide-download" :disabled="!!vm.exportData.error" @click="vm.downloadExport">Datei herunterladen</PfButton></template>
    </PfModal>

    <PfModal v-model:open="vm.familyOpen" title="Deine Produktfamilie" description="Fünf eigenständige Werkzeuge mit einer gemeinsamen Sprache und optionalem Datenaustausch." :ui="{content:'family-modal resource-modal'}"><template #body><div class="family-current"><PfIcon name="i-lucide-calendar-range" /><div><strong>Resource Atlas</strong><span>Rollen, Einsatzzeiträume und geplante Personentage.</span></div><PfBadge color="primary" variant="soft">Hier</PfBadge></div><a v-for="[key,app] in familyPeers" :key="key" class="family-app-shortcut" :href="app.file" target="_blank" rel="noopener"><PfIcon :name="app.icon" /><div><strong>{{ app.name }}</strong><span>{{ app.purpose }}</span></div><PfIcon name="i-lucide-arrow-up-right" /></a><p class="field-hint">Die optionalen Verknüpfungen öffnen gleichnamige HTML-Dateien im selben Ordner. Resource Atlas funktioniert auch ohne sie. Datenaustausch erfolgt über Familienpakete.</p></template></PfModal>
  </PfApp>
</template>
